          code: "math = __import__('math')\n\ndef comp_trap(f, a, b, n):\n    h = (b - a) / n\n    s = 0.5 * (f(a) + f(b))\n    for i in range(1, n):\n        s = s + f(a + i * h)\n    return h * s\n\ndef comp_simpson(f, a, b, n):\n    h = (b - a) / n\n    s = f(a) + f(b)\n    for i in range(1, n):\n        if i % 2 == 1:\n            s = s + 4.0 * f(a + i * h)\n        else:\n            s = s + 2.0 * f(a + i * h)\n    return h * s / 3.0\n\ndef romberg(f, a, b, m):\n    R = [[0.0] * (m + 1) for _ in range(m + 1)]\n    R[0][0] = (b - a) * (f(a) + f(b)) / 2.0\n    for i in range(1, m + 1):\n        n = 2 ** i\n        h = (b - a) / n\n        s = 0.0\n        for k in range(1, n // 2 + 1):\n            s = s + f(a + (2 * k - 1) * h)\n        R[i][0] = R[i - 1][0] / 2.0 + h * s\n        for j in range(1, i + 1):\n            R[i][j] = R[i][j - 1] + (R[i][j - 1] - R[i - 1][j - 1]) / (4.0 ** j - 1.0)\n    return R\n\na, b, exact = 0.0, math.pi, 2.0\nprint('复合梯形与复合辛普森（真值 2）:')\nprint('  步长减半看误差比，梯形应趋于 4，辛普森应趋于 16')\nprev_t = None\nprev_s = None\nfor n in (2, 4, 8, 16, 32):\n    t = comp_trap(math.sin, a, b, n)\n    s = comp_simpson(math.sin, a, b, n)\n    rt = '' if prev_t is None else '  误差比 %.2f' % (prev_t / (t - exact))\n    rs = '' if prev_s is None else '  误差比 %.2f' % (prev_s / (s - exact))\n    print('  n = %2d  梯形 %.10f  误差 %+.4e%s' % (n, t, t - exact, rt))\n    print('          辛普森 %.10f  误差 %+.4e%s' % (s, s - exact, rs))\n    prev_t = t - exact\n    prev_s = s - exact\n\nprint('')\nprint('龙贝格表（第 j 列误差为 O(h^(2j+2))，括号内是误差）:')\nR = romberg(math.sin, a, b, 4)\nfor i in range(5):\n    row = []\n    for j in range(i + 1):\n        row.append('%.10f(%+.1e)' % (R[i][j], R[i][j] - exact))\n    print('  i = %d  ' % i + '  '.join(row))\n\nprint('')\nprint('中心差商求 sin 在 x = 1 处的导数（真值 cos 1 = %.16f）:' % math.cos(1.0))\nfor h in (1e-1, 1e-3, 1e-5, 1e-6, 1e-7, 1e-8):\n    d = (math.sin(1.0 + h) - math.sin(1.0 - h)) / (2.0 * h)\n    print('  h = %.0e  近似 = %.16f  误差 = %+.3e' % (h, d, d - math.cos(1.0)))\n",
