          title: "数值实验：列主元消元、Cholesky 与三种迭代法竞赛",
          code: "math = __import__('math')\n\ndef gauss_pp(A, b):\n    n = len(A)\n    M = [A[i][:] + [b[i]] for i in range(n)]\n    for c in range(n):\n        p = c\n        for r in range(c + 1, n):\n            if abs(M[r][c]) > abs(M[p][c]):\n                p = r\n        M[c], M[p] = M[p], M[c]\n        for r in range(c + 1, n):\n            f = M[r][c] / M[c][c]\n            for k in range(c, n + 1):\n                M[r][k] = M[r][k] - f * M[c][k]\n    x = [0.0] * n\n    for r in range(n - 1, -1, -1):\n        s = M[r][n]\n        for k in range(r + 1, n):\n            s = s - M[r][k] * x[k]\n        x[r] = s / M[r][r]\n    return x\n\ndef cholesky(A):\n    n = len(A)\n    L = [[0.0] * n for _ in range(n)]\n    for i in range(n):\n        for j in range(i + 1):\n            s = A[i][j]\n            for k in range(j):\n                s = s - L[i][k] * L[j][k]\n            if i == j:\n                L[i][j] = math.sqrt(s)\n            else:\n                L[i][j] = s / L[j][j]\n    return L\n\ndef resid(A, x, b):\n    n = len(A)\n    r = [0.0] * n\n    for i in range(n):\n        s = 0.0\n        for j in range(n):\n            s = s + A[i][j] * x[j]\n        r[i] = s - b[i]\n    return r\n\ndef nrm(v):\n    s = 0.0\n    for t in v:\n        s = s + t * t\n    return math.sqrt(s)\n\ndef jacobi(A, b, x0, iters):\n    n = len(A)\n    x = x0[:]\n    hist = []\n    for k in range(iters + 1):\n        hist.append((k, x[:], nrm(resid(A, x, b))))\n        xn = x[:]\n        for i in range(n):\n            s = 0.0\n            for j in range(n):\n                if j != i:\n                    s = s + A[i][j] * x[j]\n            xn[i] = (b[i] - s) / A[i][i]\n        x = xn\n    return hist\n\ndef gs(A, b, x0, iters):\n    n = len(A)\n    x = x0[:]\n    hist = []\n    for k in range(iters + 1):\n        hist.append((k, x[:], nrm(resid(A, x, b))))\n        for i in range(n):\n            s = 0.0\n            for j in range(n):\n                if j != i:\n                    s = s + A[i][j] * x[j]\n            x[i] = (b[i] - s) / A[i][i]\n    return hist\n\nA = [[4.0, -1.0, 0.0], [-1.0, 4.0, -1.0], [0.0, -1.0, 3.0]]\nb = [2.0, 6.0, 2.0]\nxs = gauss_pp(A, b)\nprint('列主元高斯消元解 =', ['%.7f' % t for t in xs])\nprint('有理数形式 (42/41, 86/41, 56/41) =', ['%.7f' % t for t in (42 / 41.0, 86 / 41.0, 56 / 41.0)])\n\nL = cholesky(A)\nprint('')\nprint('Cholesky 因子 L:')\nfor i in range(3):\n    print('  ', ['%.7f' % L[i][j] for j in range(3)])\ns0 = L[0][0] * L[0][0]\ns1 = L[1][0] * L[1][0] + L[1][1] * L[1][1]\ns2 = L[2][0] * L[2][0] + L[2][1] * L[2][1] + L[2][2] * L[2][2]\nprint('校验 L * L^T 的对角元 =', ['%.7f' % v for v in (s0, s1, s2)])\n\nprint('')\nprint('迭代法收敛过程（残差 2-范数，6 步）:')\nprint('  步   雅可比残差      高斯-赛德尔残差')\nJ = jacobi(A, b, [0.0, 0.0, 0.0], 6)\nG = gs(A, b, [0.0, 0.0, 0.0], 6)\nfor k in range(7):\n    print('  %2d   %.10f    %.10f' % (k, J[k][2], G[k][2]))\nprint('')\nprint('雅可比第 6 步解 =', ['%.7f' % t for t in J[6][1]])\nprint('赛德尔第 6 步解 =', ['%.7f' % t for t in G[6][1]])\n\nrho_j = 0.3601790\nw = 2.0 / (1.0 + math.sqrt(1.0 - rho_j * rho_j))\nprint('')\nprint('雅可比迭代矩阵谱半径约 =', rho_j)\nprint('最优松弛因子 omega_opt = 2/(1 + sqrt(1 - rho^2)) =', w)\nprint('对应 rho_SOR = omega_opt - 1 =', w - 1.0)\n",
